#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_add_numbers_no_carry_after_N(void) {
    /* Path 2: a != NULL, b != NULL, N > 0, and after the first loop (i=0 to N-1),
     * carry == 0, so the second loop (i=N to N+9) breaks immediately.
     * We need to choose inputs such that the sum of each digit pair a[i] + b[i]
     * never exceeds 9, so no carry is generated in the first loop.
     * Then the second loop will see carry == 0 and break.
     */
    uint8_t N = 3;
    uint8_t a[3] = {1, 2, 3};   /* 321 (big-endian digits) */
    uint8_t b[20] = {4, 5, 6};  /* 654, plus extra space for N+10 */
    /* b will hold the result. Initially b = 654.
     * a + b = 321 + 654 = 975 (no digit sum > 9, so no carry).
     * Expected result in b: {5,7,9} (big-endian: 975).
     */
    int result;

    /* Call the function under test */
    result = add_numbers(a, b, N);

    /* Assertions */
    TEST_ASSERT_EQUAL_INT(0, result);  /* Function should return success */
    /* Verify the result digits */
    TEST_ASSERT_EQUAL_UINT8(5, b[0]);  /* 1+4 = 5 */
    TEST_ASSERT_EQUAL_UINT8(7, b[1]);  /* 2+5 = 7 */
    TEST_ASSERT_EQUAL_UINT8(9, b[2]);  /* 3+6 = 9 */
    /* The second loop should have broken immediately, so b[3]..b[N+9] remain unchanged.
     * Since b was not initialized beyond index 2, we cannot assert their values.
     * However, we can verify that the function did not write beyond N (since carry was 0).
     * We'll check that b[3] is still 0 (if we zero it first) or we can simply note that
     * the function is allowed to write up to N+10 elements, but with carry==0 it should
     * not write beyond N.
     * Let's zero the extra elements to make the test deterministic.
     */
    for (int i = N; i < N+10; i++) {
        b[i] = 0;
    }
    /* Re-run the addition with the cleared tail */
    result = add_numbers(a, b, N);
    TEST_ASSERT_EQUAL_INT(0, result);
    TEST_ASSERT_EQUAL_UINT8(5, b[0]);
    TEST_ASSERT_EQUAL_UINT8(7, b[1]);
    TEST_ASSERT_EQUAL_UINT8(9, b[2]);
    /* After the second call, the second loop should still break immediately,
     * so b[3] should remain 0.
     */
    TEST_ASSERT_EQUAL_UINT8(0, b[3]);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_add_numbers_no_carry_after_N);
    return UNITY_END();
}

